using System.Security.Claims;using Kaluz.Web.Services;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Authorization;
namespace Kaluz.Web.Controllers;
[Authorize]public class MaestrosController(Db db,KaluzService svc):Controller{
 static EntityDef Resolve(string tipo)=>Catalogs.All.TryGetValue(tipo,out var e)?e:throw new ArgumentException("Módulo no encontrado.");
 bool Allowed(string tipo)=>User.IsInRole("Administrador")||tipo=="Clientes";
 public IActionResult Index(string tipo="Productos",string? q=null){if(!Allowed(tipo))return Forbid();var e=Resolve(tipo);ViewBag.Tipo=tipo;ViewBag.Entity=e;ViewBag.Query=q;var sql=$"SELECT TOP 200 * FROM [{e.Table}]";if(!string.IsNullOrWhiteSpace(q)){var first=e.Fields.First(x=>x.Type=="text");sql+=$" WHERE [{first.Name}] LIKE @q";}sql+=$" ORDER BY [{e.Key}] DESC";ViewBag.Rows=string.IsNullOrWhiteSpace(q)?db.List(sql):db.List(sql,Db.P("@q","%"+q+"%"));return View();}
 [HttpGet]public IActionResult Edit(string tipo,int id=0){if(!Allowed(tipo))return Forbid();if(tipo=="Usuarios" && id>0){TempData["err"]="La edición de usuarios requiere un formulario de seguridad especializado; se permite crear y desactivar.";return RedirectToAction("Index",new{tipo});}var e=Resolve(tipo);ViewBag.Tipo=tipo;ViewBag.Entity=e;ViewBag.Opciones=ForeignOptions(tipo);ViewBag.Data=id>0?db.List($"SELECT * FROM [{e.Table}] WHERE [{e.Key}]=@id",Db.P("@id",id)).FirstOrDefault():new Dictionary<string,object?>();if(id>0&&ViewBag.Data==null)return NotFound();return View();}
 [HttpPost][ValidateAntiForgeryToken]public IActionResult Edit(string tipo,int id,IFormCollection form){if(!Allowed(tipo))return Forbid();if(tipo=="Usuarios"&&id>0)return BadRequest("No se permite modificar usuarios con el formulario genérico.");var e=Resolve(tipo);try{if(tipo=="Usuarios"&&id==0){svc.CreateUser(form["NombreCompleto"].ToString(),form["Email"].ToString(),form["Password"].ToString(),int.Parse(form["IdRol"]!));TempData["ok"]="Usuario creado.";return RedirectToAction("Index",new{tipo});}var cols=e.Fields.Select(x=>x.Name).ToArray();var vals=e.Fields.Select(x=>Parse(form[x.Name].ToString(),x.Type,x.Required)).ToArray();string sql;if(id==0){sql=$"INSERT INTO [{e.Table}] ({string.Join(",",cols.Select(x=>"["+x+"]"))}{(tipo=="Gastos"?",[IdUsuario]":"")}) VALUES ({string.Join(",",Enumerable.Range(0,cols.Length).Select(i=>"@p"+i))}{(tipo=="Gastos"?",@user":"")})";}else{sql=$"UPDATE [{e.Table}] SET {string.Join(",",cols.Select((x,i)=>"["+x+"]=@p"+i))} WHERE [{e.Key}]=@id";}var ps=vals.Select((v,i)=>Db.P("@p"+i,v)).ToList();if(id>0)ps.Add(Db.P("@id",id));if(id==0&&tipo=="Gastos")ps.Add(Db.P("@user",int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!)));db.Exec(sql,ps.ToArray());TempData["ok"]="Registro guardado correctamente.";return RedirectToAction("Index",new{tipo});}catch(Exception ex){TempData["err"]="No se pudo guardar: "+ex.Message;return RedirectToAction("Edit",new{tipo,id});}}
 Dictionary<string,List<Dictionary<string,object?>>> ForeignOptions(string tipo){
 var result=new Dictionary<string,List<Dictionary<string,object?>>>(StringComparer.OrdinalIgnoreCase);
 if(tipo=="Productos")result["IdCategoria"]=db.List("SELECT IdCategoria AS Id,Nombre FROM Categoria WHERE Activo=1 ORDER BY Nombre");
 if(tipo=="Variantes")result["IdProducto"]=db.List("SELECT IdProducto AS Id,Nombre FROM Producto WHERE Activo=1 ORDER BY Nombre");
 if(tipo=="Gastos")result["IdCategoriaGasto"]=db.List("SELECT IdCategoriaGasto AS Id,Nombre FROM CategoriaGasto ORDER BY Nombre");
 if(tipo=="Usuarios")result["IdRol"]=db.List("SELECT IdRol AS Id,Nombre FROM Rol ORDER BY Nombre");
 return result;
 }
 static object? Parse(string raw,string type,bool required){if(type=="bool")return raw=="true";if(string.IsNullOrWhiteSpace(raw)){if(required)throw new InvalidOperationException("Los campos obligatorios deben completarse.");return null;}return type switch{"number"=>int.Parse(raw),"decimal"=>decimal.Parse(raw,System.Globalization.CultureInfo.InvariantCulture),_=>raw.Trim()};}
 [HttpPost][ValidateAntiForgeryToken]public IActionResult Disable(string tipo,int id){if(!Allowed(tipo))return Forbid();var e=Resolve(tipo);if(!e.Fields.Any(x=>x.Name=="Activo"))return BadRequest();db.Exec($"UPDATE [{e.Table}] SET Activo=0 WHERE [{e.Key}]=@id",Db.P("@id",id));TempData["ok"]="Registro desactivado.";return RedirectToAction("Index",new{tipo});}
}
